const INVALID_HOST_CHARACTER_RE = /[!@#$%^&'"*()+=:;/%[\]]/;
const BRACKETED_IPV6_RE = /^\[[0-9a-f:.]+\]$/i;

function shouldNormalizeWithUrl(host) {
  return !/[\s?\\]/.test(host);
