export function normalizeHost(rawHost) {
  if (rawHost === '') {
    return '';
  }

  const loweredHost = rawHost.toLowerCase();

  if (BRACKETED_IPV6_RE.test(loweredHost)) {
    return loweredHost;
  }

  if (
    loweredHost.startsWith('.') ||
    !/[^.]/.test(loweredHost) ||
    loweredHost.includes('..') ||
    INVALID_HOST_CHARACTER_RE.test(loweredHost)
  ) {
    throw createInvalidHostError(rawHost);
  }

  if (!shouldNormalizeWithUrl(loweredHost)) {
    return loweredHost;
  }

  try {
    return new URL(`http://${loweredHost}/`).hostname;
  } catch (error) {
    if (loweredHost.includes('xn--')) {
      throw createUnicodeHostError();
    }

    throw createInvalidHostError(rawHost);
  }
}

