export class CliParseError extends Error {
  constructor(message) {
    super(message);
    this.name = "CliParseError";
  }
}

function isNegativeNumberToken(token) {
  return /^-\d+(\.\d*)?$|^-\.\d+$/.test(token);
}

function looksLikeOptionToken(token) {
  return token.length > 1 && token.startsWith("-") && !isNegativeNumberToken(token);
}

function consumeOptionValue(tokens, index, optionName) {
  const token = tokens[index];
  const equalsIndex = token.indexOf("=");

  if (equalsIndex !== -1) {
    return {
      nextIndex: index + 1,
      value: token.slice(equalsIndex + 1),
    };
  }

  const nextToken = tokens[index + 1];
  if (nextToken === undefined || looksLikeOptionToken(nextToken)) {
    throw new CliParseError(`argument ${optionName}: expected one argument`);
  }

  return {
    nextIndex: index + 2,
    value: nextToken,
  };
}

function collectUnknownTokens(tokens, index) {
  const token = tokens[index];
  const extras = [token];
  const nextToken = tokens[index + 1];

  if (token.startsWith("-") && nextToken !== undefined && !looksLikeOptionToken(nextToken)) {
    extras.push(nextToken);
    return {
      extras,
      nextIndex: index + 2,
    };
  }

  return {
    extras,
    nextIndex: index + 1,
  };
}

export function parseCommandLine(argv) {
  const values = {
    a: undefined,
    b: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length;) {
    const token = argv[index];

    if (token === "--") {
      break;
    }

    if (token === "-h" || token === "--help") {
      return {
        help: true,
        values,
      };
    }

    if (token === "--a" || token.startsWith("--a=")) {
      const parsed = consumeOptionValue(argv, index, "--a");
      values.a = parsed.value;
      index = parsed.nextIndex;
      continue;
    }

    if (token === "--b" || token.startsWith("--b=")) {
      const parsed = consumeOptionValue(argv, index, "--b");
      values.b = parsed.value;
      index = parsed.nextIndex;
      continue;
    }

    const unknown = collectUnknownTokens(argv, index);
    extras.push(...unknown.extras);
    index = unknown.nextIndex;
  }

  if (extras.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${extras.join(" ")}`);
  }

  const missing = [];
  if (values.a === undefined) {
    missing.push("--a");
  }
  if (values.b === undefined) {
    missing.push("--b");
  }

  if (missing.length > 0) {
    throw new CliParseError(`the following arguments are required: ${missing.join(", ")}`);
  }

