  if (text === "") {
    return "";
  }

  if (isBracketedIpv6Host(text)) {
    return text.toLowerCase();
  }

  if (text.startsWith(".") || hasOnlyPeriods(text) || text.includes("..") || INVALID_HOST_CHARACTERS.test(text)) {
