function splitFragment(text) {
  const index = text.indexOf("#");
  if (index === -1) {
    return {
      fragment: "",
      hasFragment: false,
      withoutFragment: text,
    };
  }

  return {
    fragment: text.slice(index + 1),
    hasFragment: true,
    withoutFragment: text.slice(0, index),
  };
}

function splitQuery(text) {
  const index = text.indexOf("?");
  if (index === -1) {
    return {
      hasQuery: false,
      query: "",
      withoutQuery: text,
    };
  }

  return {
    hasQuery: true,
    query: text.slice(index + 1),
    withoutQuery: text.slice(0, index),
  };
}

function parseAuthority(authority) {
  let username;
  let password;
  let host = "";
  let port;
  let hostPort = authority;

  const atIndex = authority.lastIndexOf("@");
  if (atIndex !== -1) {
    const userInfo = authority.slice(0, atIndex);
    hostPort = authority.slice(atIndex + 1);

    const colonIndex = userInfo.indexOf(":");
    if (colonIndex === -1) {
      username = userInfo;
    } else {
      username = userInfo.slice(0, colonIndex);
      password = userInfo.slice(colonIndex + 1);
    }
  }

  if (hostPort.startsWith("[")) {
    const closingBracketIndex = hostPort.indexOf("]");
    if (closingBracketIndex !== -1) {
      host = hostPort.slice(0, closingBracketIndex + 1).toLowerCase();
      const remainder = hostPort.slice(closingBracketIndex + 1);
      if (remainder.startsWith(":")) {
        port = remainder.slice(1);
      }
    } else {
      host = hostPort.toLowerCase();
    }
  } else {
    const lastColonIndex = hostPort.lastIndexOf(":");
    if (lastColonIndex !== -1 && hostPort.indexOf(":") === lastColonIndex) {
      host = hostPort.slice(0, lastColonIndex).toLowerCase();
      port = hostPort.slice(lastColonIndex + 1);
    } else {
      host = hostPort.toLowerCase();
    }
  }

