export function parseUrlish(rawUrl) {
  const originalText = String(rawUrl);
  const text = originalText.replace(/^\s+/, "");
  const hadLeadingWhitespace = text !== originalText;
  const schemeMatch = text.match(/^([A-Za-z][A-Za-z0-9+.-]*):(.*)$/s);
  const scheme = schemeMatch ? schemeMatch[1].toLowerCase() : "";
  const afterScheme = schemeMatch ? schemeMatch[2] : text;

  let hasAuthority = false;
  let authority = "";
  let afterAuthority = afterScheme;

  if (afterScheme.startsWith("//")) {
    hasAuthority = true;
    const authorityBody = afterScheme.slice(2);
    const authorityEnd = authorityBody.search(/[/?#]/);

    if (authorityEnd === -1) {
      authority = authorityBody;
      afterAuthority = "";
    } else {
      authority = authorityBody.slice(0, authorityEnd);
      afterAuthority = authorityBody.slice(authorityEnd);
    }
  }

  const fragmentParts = splitFragment(afterAuthority);
  const queryParts = splitQuery(fragmentParts.withoutFragment);
  const authorityParts = parseAuthority(authority);
  const path = normalizePath(queryParts.withoutQuery);

  if (hadLeadingWhitespace) {
    return {
      hasAuthority: false,
      hasFragment: fragmentParts.hasFragment,
      hasQuery: queryParts.hasQuery,
      fragment: fragmentParts.fragment,
      host: "",
      password: undefined,
      path,
      port: undefined,
      query: queryParts.query,
      scheme: "",
      username: undefined,
    };
  }

  return {
    ...authorityParts,
    hasAuthority,
    hasFragment: fragmentParts.hasFragment,
    hasQuery: queryParts.hasQuery,
    fragment: fragmentParts.fragment,
    path,
    query: queryParts.query,
