function serializeAuthority(model) {
  let authority = "";

  if (model.username !== undefined || model.password !== undefined) {
    authority += model.username ?? "";
    if (model.password !== undefined) {
      authority += `:${model.password}`;
    }
    authority += "@";
  }

  authority += model.host ?? "";

  if (model.port !== undefined) {
    authority += `:${model.port}`;
  }

  return authority;
}

function serializePathWithAuthority(path, authority, scheme) {
  if (path === "") {
    return "";
  }

  if ((authority !== "" || scheme !== "") && !path.startsWith("/")) {
    return `/${path}`;
  }

  return path;
}

export function serializeUrlish(model) {
  let output = "";

  if (model.scheme !== "") {
    output += `${model.scheme}:`;
  }

  if (model.hasAuthority) {
    const authority = serializeAuthority(model);
    output += `//${authority}`;
    output += serializePathWithAuthority(model.path, authority, model.scheme);
  } else {
    output += model.path;
  }

  if (model.hasQuery) {
    output += `?${model.query}`;
  }

  if (model.hasFragment) {
    output += `#${model.fragment}`;
  }

  return output;
}
